import { Component, inject, signal } from '@angular/core'
import { HttpClient } from '@angular/common/http'
import { FormControl, ReactiveFormsModule } from '@angular/forms'
import { mergeMap } from 'rxjs'

type Hit = { id: string; title: string }

@Component({
  selector: 'app-search',
  standalone: true,
  imports: [ReactiveFormsModule],
  template: `
    <input [formControl]="query" type="search" />
    <ul>
      @for (hit of hits(); track hit.id) {
        <li>{{ hit.title }}</li>
      }
    </ul>
  `,
})
export class SearchComponent {
  private http = inject(HttpClient)
  query = new FormControl('', { nonNullable: true })
  hits = signal<Hit[]>([])

  constructor() {
    this.query.valueChanges
      .pipe(mergeMap((q) => this.search(q)))
      .subscribe((hits) => this.hits.set(hits))
  }

  private search(q: string) {
    return this.http.get<Hit[]>('/api/search', { params: { q } })
  }
}

